    // Part II. Oracles for exactly-1 3-SAT problem
    //////////////////////////////////////////////////////////////////

    // ------------------------------------------------------
    function F_Exactly1One (args : Bool[]) : Bool {
        mutable nOnes = 0;
        for element in args {
            if element {
                set nOnes += 1;
            }
        }
        return nOnes == 1;
    }


